session_start();require_once "../config/db.php";require_once "../includes/auth_check.php";require_once "return_helpers.php";$role=$_SESSION['role']??'';if(!in_array($role,returnsAllowedRoles(),true))die('Access denied!');$id=(int)($_GET['id']??0);$stmt=$conn->prepare("SELECT r.*,u.full_name returned_by_name FROM `returns` r LEFT JOIN users u ON u.id=r.returned_by WHERE r.id=? LIMIT 1");$stmt->execute([$id]);$r=$stmt->fetch(PDO::FETCH_ASSOC);if(!$r)die('Return record not found.');function dashboardHref(string $r):string{if($r==='super_admin')return '../dashboard/superadmindashboard';if($r==='manager')return '../dashboard/managerdashboard';return '../dashboard/inventorydashboard';}
