<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars($r['return_number']) ?></title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css"><style>@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');:root{--p:#1a4b2a;--g:#f3f4f6;--b:#e5e7eb;--m:#6b7280}*{box-sizing:border-box}body{margin:0;font-family:Inter,sans-serif;background:var(--g)}.main{margin-left:260px;width:calc(100% - 260px);padding:2rem}.header,.card{background:#fff;border:1px solid var(--b);border-radius:1rem}.header{padding:1.5rem 2rem;margin-bottom:1.5rem}.header h1{margin:0 0 .4rem}.crumb{font-size:.85rem;color:var(--m)}.crumb a{color:var(--p);text-decoration:none}.card{padding:1.5rem;max-width:900px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:0 2rem}.item{padding:.75rem 0;border-bottom:1px solid var(--b)}.lab{font-size:.72rem;color:var(--m);font-weight:700;text-transform:uppercase}.val{margin-top:.25rem}.wide{grid-column:1/-1}.ok{background:#ecfdf5;border:1px solid #a7f3d0;color:#065f46;padding:.9rem;border-radius:.5rem;margin-bottom:1rem}.btn{display:inline-flex;margin-top:1.25rem;padding:.7rem 1rem;border-radius:.5rem;background:var(--p);color:#fff;text-decoration:none}@media(max-width:1200px){.main{margin-left:0!important;width:100%!important;padding:5rem 1rem 1rem!important}}@media(max-width:650px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><?php include "../includes/sidebar.php"; ?><div class="main"><div class="header"><h1><i class="fas fa-receipt" style="color:var(--p)"></i> <?= htmlspecialchars($r['return_number']) ?></h1><div class="crumb"><a href="<?= htmlspecialchars(dashboardHref($role)) ?>">Dashboard</a> / <a href="./">Returns</a> / Details</div></div><?php if(isset($_GET['created'])): ?><div class="ok"><i class="fas fa-check-circle"></i> Return recorded successfully.</div><?php endif; ?><div class="card"><div class="grid"><div class="item"><div class="lab">Category</div><div class="val"><?= htmlspecialchars(returnCategoryLabel($r['category'])) ?></div></div><div class="item"><div class="lab">Item ID / Serial</div><div class="val"><?= htmlspecialchars($r['item_identifier']) ?></div></div><div class="item wide"><div class="lab">Description</div><div class="val"><?= htmlspecialchars($r['description']??'N/A') ?></div></div><div class="item"><div class="lab">Client</div><div class="val"><?= htmlspecialchars($r['client_name']??'N/A') ?></div></div><div class="item"><div class="lab">Phone</div><div class="val"><?= htmlspecialchars($r['client_phone']??'N/A') ?></div></div><div class="item"><div class="lab">Quantity</div><div class="val"><?= (int)$r['quantity'] ?></div></div><div class="item"><div class="lab">Unit Price</div><div class="val"><?= $r['unit_price']!==null?'KES '.number_format((float)$r['unit_price'],2):'N/A' ?></div></div><div class="item"><div class="lab">Refund</div><div class="val"><?= $r['refund_amount']!==null?'KES '.number_format((float)$r['refund_amount'],2):'N/A' ?></div></div><div class="item"><div class="lab">Condition</div><div class="val"><?= htmlspecialchars($r['return_condition']) ?></div></div><div class="item"><div class="lab">Inventory Action</div><div class="val"><?= $r['stock_action']==='restock'?'Returned to stock':'Held for inspection' ?></div></div><?php if(!empty($r['replacement_identifier'])): ?><div class="item"><div class="lab">Replacement Serial</div><div class="val"><?= htmlspecialchars($r['replacement_identifier']) ?></div></div><div class="item"><div class="lab">Replacement Selling Price</div><div class="val">KES <?= number_format((float)$r['replacement_price'],2) ?></div></div><div class="item wide"><div class="lab">Replacement Specs</div><div class="val"><?= htmlspecialchars($r['replacement_description']??'N/A') ?></div></div><?php endif; ?><div class="item"><div class="lab">Branch</div><div class="val"><?= htmlspecialchars($r['branch']??'N/A') ?></div></div><div class="item"><div class="lab">Returned By</div><div class="val"><?= htmlspecialchars($r['returned_by_name']??'N/A') ?></div></div><div class="item"><div class="lab">Date</div><div class="val"><?= date('M j, Y g:i A',strtotime($r['returned_at'])) ?></div></div><div class="item wide"><div class="lab">Reason</div><div class="val"><?= htmlspecialchars($r['return_reason']) ?></div></div><div class="item wide"><div class="lab">Notes</div><div class="val"><?= nl2br(htmlspecialchars($r['notes']??'N/A')) ?></div></div></div><a class="btn" href="./"><i class="fas fa-arrow-left"></i>&nbsp; Back to Returns</a></div></div></body></html>
